#[derive(Clone,Debug,Eq,Error,PartialEq)]pub enum DomainError{#[error("invalid identity field")]Invalid,#[error("generation zero")]GenerationZero,#[error("invalid address")]Address,#[error("identical base and quote")]IdenticalBaseQuote,#[error("invalid instrument")]Instrument,#[error(transparent)]Decimal(#[from]DecimalError)}
#[derive(Clone,Debug,Eq,Hash,PartialEq,Serialize,Deserialize)]#[serde(rename_all="snake_case")]pub enum AssetNamespace{Native,Fiat,Evm,Solana,Cosmos,Other(String)}
#[derive(Clone,Debug,Eq,Hash,PartialEq,Serialize)]pub struct AssetId{namespace:AssetNamespace,chain:String,address:String,symbol:String,generation:u32}
#[derive(Deserialize)]struct AssetWire{namespace:AssetNamespace,chain:String,address:String,symbol:String,generation:u32}
impl AssetId{pub fn new(namespace:AssetNamespace,chain:impl Into<String>,address:impl Into<String>,symbol:impl Into<String>,generation:u32)->Result<Self,DomainError>{let chain=chain.into();let mut address=address.into();let symbol=symbol.into();token(&chain,64,false)?;token(&symbol,32,true)?;if generation==0{return Err(DomainError::GenerationZero)}match namespace{AssetNamespace::Native|AssetNamespace::Fiat if !address.is_empty()=>return Err(DomainError::Address),AssetNamespace::Evm=>{if address.len()!=42||!address.starts_with("0x")||!address[2..].bytes().all(|b|b.is_ascii_hexdigit()){return Err(DomainError::Address)}address=address.to_ascii_lowercase()},AssetNamespace::Solana if !(32..=44).contains(&address.len())=>return Err(DomainError::Address),AssetNamespace::Cosmos if !address.contains('1')=>return Err(DomainError::Address),_=>{}}Ok(Self{namespace,chain,address,symbol,generation})}pub fn namespace(&self)->&AssetNamespace{&self.namespace}pub fn chain(&self)->&str{&self.chain}pub fn address(&self)->&str{&self.address}pub fn symbol(&self)->&str{&self.symbol}pub const fn generation(&self)->u32{self.generation}}
impl<'de>Deserialize<'de> for AssetId{fn deserialize<D:Deserializer<'de>>(d:D)->Result<Self,D::Error>{let w=AssetWire::deserialize(d)?;Self::new(w.namespace,w.chain,w.address,w.symbol,w.generation).map_err(D::Error::custom)}}
impl fmt::Display for AssetId{fn fmt(&self,f:&mut fmt::Formatter<'_>)->fmt::Result{write!(f,"{:?}:{}:{}:{}:{}",self.namespace,self.chain,self.address,self.symbol,self.generation)}}
macro_rules! id{($n:ident)=>{#[derive(Clone,Debug,Eq,Hash,Ord,PartialEq,PartialOrd,Serialize,Deserialize)]#[serde(try_from="String",into="String")]pub struct $n(String);impl $n{pub fn new(v:impl Into<String>)->Result<Self,DomainError>{let v=v.into();token(&v,128,false)?;Ok(Self(v))}pub fn as_str(&self)->&str{&self.0}}impl TryFrom<String> for $n{type Error=DomainError;fn try_from(v:String)->Result<Self,Self::Error>{Self::new(v)}}impl From<$n> for String{fn from(v:$n)->Self{v.0}}impl fmt::Display for $n{fn fmt(&self,f:&mut fmt::Formatter<'_>)->fmt::Result{f.write_str(&self.0)}}};}
id!(VenueId);id!(ModelPackageId);id!(ForecastId);id!(EvidenceBundleId);
