impl InstrumentId{pub fn new(venue:VenueId,symbol:impl Into<String>,generation:u32)->Result<Self,DomainError>{let venue_symbol=symbol.into();if venue_symbol.is_empty()||venue_symbol.len()>96||generation==0{return Err(DomainError::Invalid)}Ok(Self{venue,venue_symbol,generation})}pub fn venue(&self)->&VenueId{&self.venue}pub fn venue_symbol(&self)->&str{&self.venue_symbol}pub const fn generation(&self)->u32{self.generation}}
