impl InstrumentDefinition{pub fn new(input:InstrumentDefinitionInput)->Result<Self,DomainError>{if input.base_asset==input.quote_asset{return Err(DomainError::IdenticalBaseQuote)}if input.quantity_step.value().is_zero()||!input.contract_multiplier.is_positive(){return Err(DomainError::Instrument)}match input.contract_kind{ContractKind::None|ContractKind::Linear if input.settlement_asset!=input.quote_asset=>return Err(DomainError::Instrument),ContractKind::Inverse if input.settlement_asset!=input.base_asset=>return Err(DomainError::Instrument),_=>{}}match input.product_type{ProductType::Spot if input.contract_kind!=ContractKind::None||input.expiry.is_some()||input.strike.is_some()=>return Err(DomainError::Instrument),ProductType::Perpetual if input.contract_kind==ContractKind::None||input.expiry.is_some()=>return Err(DomainError::Instrument),ProductType::Future if input.contract_kind==ContractKind::None||input.expiry.is_none()=>return Err(DomainError::Instrument),ProductType::Option if input.contract_kind==ContractKind::None||input.expiry.is_none()||input.strike.is_none()||input.option_side.is_none()=>return Err(DomainError::Instrument),_=>{}}Ok(Self{input})}pub fn id(&self)->&InstrumentId{&self.input.id}pub fn base_asset(&self)->&AssetId{&self.input.base_asset}pub fn quote_asset(&self)->&AssetId{&self.input.quote_asset}pub fn settlement_asset(&self)->&AssetId{&self.input.settlement_asset}pub const fn product_type(&self)->ProductType{self.input.product_type}pub const fn contract_kind(&self)->ContractKind{self.input.contract_kind}pub const fn price_tick(&self)->Price{self.input.price_tick}pub const fn quantity_step(&self)->Quantity{self.input.quantity_step}pub const fn contract_multiplier(&self)->FixedDecimal{self.input.contract_multiplier}pub fn quote_notional(&self,contracts:Quantity,price:Price)->Result<Notional,DomainError>{let v=match self.input.contract_kind{ContractKind::Inverse=>contracts.value().checked_mul(self.input.contract_multiplier)?,_=>contracts.value().checked_mul(self.input.contract_multiplier)?.checked_mul(price.value())?};Ok(Notional::new(v)?)}}
#[derive(Clone,Copy,Debug,Eq,Hash,PartialEq,Serialize,Deserialize)]pub struct RunId(Uuid);impl RunId{pub fn now_v7()->Self{Self(Uuid::now_v7())}}
fn token(v:&str,max:usize,upper:bool)->Result<(),DomainError>{if v.is_empty()||v.len()>max||!v.is_ascii(){return Err(DomainError::Invalid)}let ok=v.bytes().all(|b|if upper{b.is_ascii_uppercase()||b.is_ascii_digit()||matches!(b,b'-'|b'_'|b'.')}else{b.is_ascii_lowercase()||b.is_ascii_digit()||matches!(b,b'-'|b'_'|b'.'|b':'|b'@')});if ok{Ok(())}else{Err(DomainError::Invalid)}}
